import numpy as np

def get_neighbors(pos):
    x, y = pos
    return [(x+1, y), (x-1, y), (x, y+1), (x, y-1)]

def is_connected(squares):
    if not squares: return True
    visited = set()
    stack = [list(squares)[0]]
    visited.add(stack[0])
    while stack:
        curr = stack.pop()
        for n in get_neighbors(curr):
            if n in squares and n not in visited:
                visited.add(n)
                stack.append(n)
    return len(visited) == len(squares)

def is_simply_connected(squares):
    # A polyomino is simply connected if it has no holes.
    # This means the number of squares S, the number of edges E,
    # and the number of faces F (including the outer face) satisfy
    # V - E + F = 2. For a grid polyomino, V is the number of vertices,
    # E is the number of edges of the boundary.
    # Alternatively, a polyomino is simply connected if its complement
    # is connected.
    if not squares: return True

    # Get all squares in the bounding box plus a border
    min_x = min(s[0] for s in squares) - 1
    max_x = max(s[0] for s in squares) + 1
    min_y = min(s[1] for s in squares) - 1
    max_y = max(s[1] for s in squares) + 1

    all_squares = set()
    for x in range(min_x, max_x + 1):
        for y in range(min_y, max_y + 1):
            all_squares.add((x, y))

    complement = all_squares - squares

    # Check if complement is connected
    if not complement: return True
    start_node = list(complement)[0]
    visited = set()
    stack = [start_node]
    visited.add(start_node)
    while stack:
        curr = stack.pop()
        for n in get_neighbors(curr):
            if n in complement and n not in visited:
                visited.add(n)
                stack.append(n)

    return len(visited) == len(complement)

